def stability_status(current_pct: float | None, prior_pct: float | None, tolerance: float = 0.10) -> str:
    """Return WARN, PASS, or SKIP when a share is missing."""
    if current_pct and prior_pct:
        change = abs(current_pct - prior_pct)
        return "WARN" if change > tolerance else "PASS"
    return "SKIP"

